18	
19	public class CharMovement
20	{
21		private Character c;
22	
23		public CharMovement(Character c)
24		{
25			this.c = c;
26		}
27	
28		public void Move(Vector2 pLoc, Vector2 move)
29		{
30			if (Game1.fastForwardMode)
31			{
32				c.traj = default;
33			}
34			int layer = CharCols.GetLayer(pLoc + new Vector2(0f, -10f));
35			float num = 20f;
36			float num2 = 80f;
37			float num3 = 16f;
38			int num4 = -1;
39			Player mainPlayer = GameStateManager.GetMainPlayer();
40			if (mainPlayer != null)
41			{
42				num4 = mainPlayer.camMgr.latestArenaIdx;
43			}
44			if (GameStateManager.coopPlayerIdx > -1)
45			{
46				Player coopPlayer = PlayerMgr.GetCoopPlayer();
47				if (coopPlayer != null && coopPlayer.charIdx == c.ID)
48				{
49					num4 = coopPlayer.camMgr.latestArenaIdx;
50				}
51			}
52			bool flag = false;
53			bool upsideDown = c.buffs.GetUpsideDown();
54			bool flag2 = false;
55			Vector2 vector = pLoc;
56			float num5 = -110f;
57			float num6 = num5 - 16f;
58			float num7 = 10f;
59			float num8 = 1f;
60			if (upsideDown)
61			{
62				num8 = -1f;
63			}
64			if (CharCols.TestCol(c.loc + new Vector2(num, -10f * num8), falling: false, 0f))
65			{
66				if (c.traj.X > 0f)
67				{
68					c.traj.X = 0f;
69				}
70				else
71				{
72					c.traj.X = -300f;
73				}
74			}
75			if (CharCols.TestCol(c.loc + new Vector2(0f - num, -10f * num8), falling: false, 0f))
76			{
77				if (c.traj.X < 0f)
78				{
79					c.traj.X = 0f;
80				}
81				else
82				{
83					c.traj.X = 300f;
84				}
85			}
86			int col;
87			if (move.X != 0f)
88			{
89				int num9 = 1;
90				float num10 = ((move.X < 0f) ? (0f - move.X) : move.X);
91				if (num10 > num3)
92				{
93					num9 = 1 + (int)(num10 / num3);
94				}
95				move.X /= num9;
96				for (int i = 0; i < num9; i++)
97				{
98					int groundCol = CharCols.GetGroundCol(c);
99					c.loc.X += move.X;
100					if (num4 > -1)
101					{
102						int activeArenaIdx = MapMgr.map.triggerMgr.GetActiveArenaIdx(c);
103						if (activeArenaIdx != num4)
104						{
105							Vector2 loc = c.loc;
106							c.loc = pLoc;
107							int activeArenaIdx2 = MapMgr.map.triggerMgr.GetActiveArenaIdx(c);
108							c.loc = loc;
109							if (activeArenaIdx == -1 && activeArenaIdx2 != -1)
110							{
111								c.loc.X = pLoc.X;
112							}
113						}
114						else if (c.playerIdx == -1 && !c.boss)
115						{
116							Vector2 loc2 = c.loc;
117							c.loc = pLoc;
118							int activeArenaIdx3 = MapMgr.map.triggerMgr.GetActiveArenaIdx(c);
119							c.loc = loc2;
120							if (activeArenaIdx > -1 && activeArenaIdx3 == -1)
121							{
122								c.loc.X = pLoc.X;
123							}
124						}
125					}
126					if (num4 < 0 && MapMgr.map.triggerMgr.GetActiveArenaIdx(c) > -1 && c.boss)
127					{
128						c.loc = pLoc;
129					}
130					if (c.sanctuaryIdx > -1)
131					{
132						bool flag3 = false;
133						bool flag4 = false;
134						flag3 = layer == 2;
135						flag4 = CharCols.GetLayer(c.loc + new Vector2(0f, -10f)) == 2;
136						if ((c.charAI.job != 4 || c.charAI.attackType != 43) && flag3 && !flag4)
137						{
138							c.loc.X = pLoc.X;
139							c.charAI.job = 4;
140							c.charAI.jobFrame = 4f;
141						}
142					}
143					if (c.state == 0)
144					{
145						if (CharCols.GetCol(c.loc + new Vector2(0f, 4f)) == 1)
146						{
147							col = CharCols.GetCol(c.loc + new Vector2(0f, -4f));
148							if ((uint)(col - 2) <= 1u)
149							{
150								c.loc.Y = CharCols.GetGround(new Vector2(c.loc.X, c.loc.Y - 32f));
151							}
152						}
153						switch (groundCol)
154						{
155						case 2:
156						case 3:
157						case 6:
158						case 7:
159							c.loc.Y = CharCols.GetLedgeY(pLoc, c.loc);
160							break;
161						case 8:
162						case 9:
163							if (c.keys.keyDown)
164							{
165								float num11 = c.loc.X / 64f;
166								num11 -= (float)(int)num11;
167								if (move.X < 0f && groundCol == 8)
168								{
169									if (num11 > 0.75f)
170									{
171										c.loc.Y += 2f;
172									}
173								}
174								else if (move.X > 0f && groundCol == 9 && num11 < 0.25f)
175								{
176									c.loc.Y += 2f;
177								}
178							}
179							c.loc.Y = CharCols.GetLedgeY(pLoc, c.loc);
180							break;
181						}
182						if (((uint)(groundCol - 2) <= 1u || (uint)(groundCol - 6) <= 3u) && (int)(c.loc.X / 64f) != (int)(pLoc.X / 64f))
183						{
184							CharCols.GetCol(c.loc + new Vector2(0f, -1f));
185							int col2 = CharCols.GetCol(c.loc + new Vector2(0f, 1f));
186							if (col2 == 1 || col2 == 5)
187							{
188								c.loc.Y = CharCols.GetMinY(c.loc);
189								if (upsideDown)
190								{
191									c.loc.Y += 32f;
192								}
193							}
194						}
195						if ((groundCol == 0 || groundCol == 5 || (uint)(groundCol - 8) <= 1u) && (int)(c.loc.X / 64f) != (int)(pLoc.X / 64f))
196						{
197							int col3 = CharCols.GetCol(c.loc + new Vector2(0f, -1f));
198							int col4 = CharCols.GetCol(c.loc + new Vector2(0f, 1f));
199							bool flag5 = !c.keys.keyDown || col4 == 0;
