515		public void CheckFalloff(Vector2 pLoc)
516		{
517			int groundCol = CharCols.GetGroundCol(c);
518			MonsterDef monsterDef = MonsterCatalog.catalog[c.monsterIdx];
519			float num = 30f;
520			if (c.buffs.GetUpsideDown())
521			{
522				num = 0f - num;
523			}
524			if (c.platform > -1)
525			{
526				MapMgr.entityMgr.platform[c.platform].UpdateCharacter(c, pLoc, MapMgr.GetMap(), drawOnly: false);
527				if (c.platform == -1 && !CharCols.TestCol(c.loc + new Vector2(-20f, num), falling: true, 0f) && !CharCols.TestCol(c.loc + new Vector2(20f, num), falling: true, 0f))
528				{
529					c.state = 1;
530					c.traj.Y = -10f;
531					c.anim.SetAnimation("fly");
532					c.update.dropFrame = 0.25f;
533					if (c.traj.X < 0f && c.traj.X > -200f)
534					{
535						c.traj.X = -200f;
536					}
537					if (c.traj.X > 0f && c.traj.X < 200f)
538					{
539						c.traj.X = 200f;
540					}
541				}
542				return;
543			}
544			switch (groundCol)
545			{
546			case 2:
547			case 3:
548			case 6:
549			case 7:
550				c.loc.Y = CharCols.GetLedgeY(pLoc, c.loc);
551				return;
552			case 8:
553			case 9:
554				c.loc.Y = CharCols.GetLedgeY(pLoc, c.loc);
555				return;
556			}
557			if (c.platform == -1)
558			{
559				int num2 = MapMgr.entityMgr.CheckPlatform(c, c.loc + new Vector2(0f, -1f), c.loc);
560				if (num2 > -1)
561				{
562					c.platform = num2;
563					return;
564				}
565			}
566			if (!CharCols.TestCol(c.loc + new Vector2(-20f, num), falling: true, 0f) && !CharCols.TestCol(c.loc + new Vector2(20f, num), falling: true, 0f))
567			{
568				if ((monsterDef.GetRun(c) && monsterDef.ai != 2) || c.anim.animName == "hit" || c.anim.animName == "lroll" || c.anim.animName == "roll" || c.anim.animName == "froll" || c.anim.animName == "mroll" || c.anim.animName == "stagger" || monsterDef.GetIdle(c))
569				{
570					c.state = 1;
571					c.traj.Y = -10f;
572					switch (c.anim.animName)
573					{
574					case "lroll":
575					case "roll":
576					case "mroll":
577					case "froll":
578						if (c.traj.X > 500f)
579						{
580							c.traj.X = 500f;
581						}
582						if (c.traj.X < -500f)
583						{
584							c.traj.X = -500f;
585						}
586						break;
587					case "hit":
588						c.anim.SetAnimation("fhit");
589						break;
590					default:
591						c.anim.SetAnimation("fly");
592						break;
593					}
594					if (c.traj.X < 0f && c.traj.X > -200f)
595					{
596						c.traj.X = -200f;
597					}
598					if (c.traj.X > 0f && c.traj.X < 200f)
599					{
600						c.traj.X = 200f;
601					}
602				}
603				else
604				{
605					c.loc = pLoc;
606				}
607			}
608			if (c.state == 0 && (!CharCols.TestCol(c.loc + new Vector2(-30f, num), falling: true, 0f) || !CharCols.TestCol(c.loc + new Vector2(30f, num), falling: true, 0f)) && (!monsterDef.GetRun(c) || monsterDef.ai == 2) && c.anim.animName != "stagger" && c.anim.animName != "lroll" && c.anim.animName != "roll" && c.anim.animName != "mroll" && c.anim.animName != "froll")
609			{
610				if (monsterDef.ai == 2)
611				{
612					c.charAI.attackType = 0;
613					c.charAI.attackFrame = -0.5f;
614				}
615				if (!CharCols.TestCol(c.loc + new Vector2(-30f, num), falling: true, 0f))
616				{
617					if (c.traj.X < 100f)
618					{
619						c.traj.X = 100f;
620					}
621					if (CharCols.TestCol(c.loc + new Vector2(30f, num), falling: true, 0f))
622					{
623						float num3 = (float)(int)((c.loc.X + 30f) / 64f) * 64f + 20f;
624						if (c.loc.X < num3)
625						{
626							c.loc.X = num3;
627						}
628					}
629				}
630				if (!CharCols.TestCol(c.loc + new Vector2(30f, num), falling: true, 0f))
631				{
632					if (c.traj.X > -100f)
633					{
634						c.traj.X = -100f;
635					}
636					if (CharCols.TestCol(c.loc + new Vector2(-30f, num), falling: true, 0f))
637					{
638						float num4 = (float)((int)((c.loc.X - 30f) / 64f) + 1) * 64f - 20f;
639						if (c.loc.X > num4)
640						{
641							c.loc.X = num4;
642						}
643					}
644				}
645			}
646			if (c.state != 0)
647			{
648				return;
649			}
650			groundCol = CharCols.GetCol(c.loc + new Vector2(0f, 4f));
651			if ((uint)(groundCol - 90) <= 7u)
652			{
653				bool flag = false;
654				switch (groundCol)
