657					flag = BlinkPlatMgr.mainBlinkPhase[0] == 0;
658					break;
659				case 91:
660					flag = BlinkPlatMgr.mainBlinkPhase[1] == 0;
661					break;
662				case 92:
663					flag = BlinkPlatMgr.quickBlinkPhase[0] == 0;
664					break;
665				case 93:
666					flag = BlinkPlatMgr.quickBlinkPhase[1] == 0;
667					break;
668				case 94:
669					flag = BlinkPlatMgr.quickBlinkPhase[2] == 0;
670					break;
671				case 95:
672					flag = BlinkPlatMgr.quickBlinkPhase[3] == 0;
673					break;
674				case 96:
675					flag = BlinkPlatMgr.quickBlinkPhase[4] == 0;
676					break;
677				case 97:
678					flag = BlinkPlatMgr.quickBlinkPhase[5] == 0;
679					break;
680				}
681				if (flag)
682				{
683					c.traj.Y = 0f;
684					c.state = 1;
685					c.anim.SetAnimation("fly");
686				}
687			}
688		}
