		{
			gotos[i] = -1;
		}
		mashThreshGoto = -1;
	}

	public void UpdateGotos(Character c, CharKeys charKeys)
	{
		if (charKeys.keyAttack)
		{
			lastKey = 1;
		}
		if (charKeys.keyItem && c.update.canKeyItem && c.equipment.useConsumable > -1 && c.equipment.useConsumable < c.equipment.consumable.Length && c.equipment.usePickerConsumableInvIdx < 0 && c.equipment.consumable[c.equipment.useConsumable].catalogIdx > -1 && c.equipment.consumable[c.equipment.useConsumable].invIdx > -1 && c.equipment.selConsumable == c.equipment.useConsumable)
		{
			if (c.playerIdx > -1)
			{
				Player player = PlayerMgr.player[c.playerIdx];
				if (player.playerInv.inventory[c.equipment.consumable[c.equipment.useConsumable].invIdx] != null && player.playerInv.inventory[c.equipment.consumable[c.equipment.useConsumable].invIdx].count > 0)
				{
					lastKey = 7;
				}
			}
			else
			{
				lastKey = 7;
			}
		}
		if (charKeys.keyAttack && charKeys.keyDown)
		{
			lastKey = 2;
		}
		if (charKeys.keyAttack && charKeys.keyUp)
		{
			lastKey = 3;
		}
		if (charKeys.keyStrong)
		{
			lastKey = 4;
			int weightClass = c.stats.GetWeightClass(null);
			if ((uint)weightClass <= 1u)
			{
				lastKey = 8;
			}
		}
		if (charKeys.keyOff)
		{
			lastKey = 14;
		}
		if (charKeys.keyJump)
		{
			lastKey = 13;
		}
		if (charKeys.keySpecial && !c.equipment.HasSwordShieldLoadout())
		{
			lastKey = 4;
		}
		if (gotos[11] > -1 && !charKeys.keyHoldX)
		{
			lastKey = 11;
		}

	}
	if (gotos[12] > -1 && !charKeys.keyHoldX && !charKeys.keyHoldB && !charKeys.keyBlock)
	{
		lastKey = 12;
	}
	if (gotos[11] > -1)
	{
		c.update.chargeVal += Game1.frameTime;
