	internal void AddSalt(MonsterDef mDef, Character c)
	{
		float num = 1f;
		Character playerCharacter = CharMgr.GetPlayerCharacter(this);
		if (PlayerMgr.IsSaltCharacter(c))
		{
			num = 2f;
		}
		if (playerCharacter != null)
		{
			if (playerCharacter.stats.GetRingFlag(8))
			{
				num = 1.1f;
			}
			if (playerCharacter.equipment.loadout[playerCharacter.equipment.loadoutIdx, 0].catalogIdx > -1 && playerCharacter.equipment.loadout[playerCharacter.equipment.loadoutIdx, 0].catalogIdx < LootCatalog.category[0].loot.Length && LootCatalog.category[0].loot[playerCharacter.equipment.loadout[playerCharacter.equipment.loadoutIdx, 0].catalogIdx].flags == 12)
			{
				num *= 1.25f;
			}
		}
		if (PlayerMgr.GetMainPlayer().sanctuaryBonus[7])
		{
			num *= 1.1f;
		}
		float num2 = mDef.salt;
		if (num2 <= 0f)
		{
			return;
		}
		if (PlayerMgr.GetMainPlayer() != null && PlayerMgr.GetMainPlayer().IsScaledRandomizer())
		{
			num2 = RandomizerMgr.GetTierAdjustSalt(c);
		}
		if (GameStateManager.playthroughCount > 0)
		{
			num2 += 400f + 100f * (float)GameStateManager.playthroughCount;
			if (c.boss)
			{
				num2 += 50000f + 10000f * (float)GameStateManager.playthroughCount;
			}
			num += num * 0.2f * (float)GameStateManager.playthroughCount;
		}
		AddSalt((int)(num2 * num), 1f);
	}

	internal void AddSalt(int salt, float delay)
	{
		for (int i = 0; i < saltAdd.Length; i++)
		{
			if (saltAdd[i].frame <= 0f)
			{
				saltAdd[i] = new SaltAdd(delay, salt);
				return;
			}
		}
		saltAdd[0].count += salt;
	}

