using Microsoft.Xna.Framework;

namespace ProjectTower.player;

public class PlayerQuake
{
	private Player p;

	public float quake;

	public PlayerQuake(Player player)
	{
		p = player;
	}

	public void Update()
	{
		if (quake > 0f)
		{
			quake -= Game1.frameTime;
		}
	}

	public void SetQuake(float v, Vector2 loc)
	{
		if (loc.X < p.camMgr.tL.X || loc.Y < p.camMgr.tL.Y || loc.X > p.camMgr.bR.X || loc.Y > p.camMgr.bR.Y)
		{
			return;
		}
		float num = (loc - p.camMgr.scroll).LengthSquared() / 4000000f;
		if (num < 1f)
		{
			v *= 1f - num;
			if (v > quake)
			{
				quake = v;
			}
		}
	}
}
using System.IO;

namespace ProjectTower.player;

public class PlayerBeast
{
	public int kills;

	public int killedBy;

	public int[] drops;

	public PlayerBeast()
	{
		kills = 0;
		killedBy = 0;
		drops = new int[6];
	}

	public PlayerBeast(BinaryReader reader)
	{
		kills = reader.ReadInt32();
		killedBy = reader.ReadInt32();
		drops = new int[6];
		for (int i = 0; i < drops.Length; i++)
		{
			drops[i] = reader.ReadInt32();
		}
	}

	public PlayerBeast(PlayerBeast playerBeast)
	{
		kills = playerBeast.kills;
		killedBy = playerBeast.killedBy;
		drops = new int[6];
		for (int i = 0; i < drops.Length; i++)
		{
			drops[i] = playerBeast.drops[i];
		}
	}

	internal void Write(BinaryWriter writer)
	{
		writer.Write(kills);
		writer.Write(killedBy);
		for (int i = 0; i < drops.Length; i++)
		{
			writer.Write(drops[i]);
		}
	}
}
