namespace ProjectTower.player;

public class PlayerBeasts
{
	private Player player;

	public Dictionary<string, PlayerBeast> playerBeast;

	public PlayerBeasts(Player player)
	{
		this.player = player;
		playerBeast = new Dictionary<string, PlayerBeast>();
	}

	public void Write(BinaryWriter writer)
	{
		writer.Write(playerBeast.Count);
		foreach (KeyValuePair<string, PlayerBeast> item in playerBeast)
		{
			writer.Write(item.Key);
			item.Value.Write(writer);
		}
	}

	public void Read(BinaryReader reader)
	{
		playerBeast = new Dictionary<string, PlayerBeast>();
		int num = reader.ReadInt32();
		for (int i = 0; i < num; i++)
		{
			string key = reader.ReadString();
			PlayerBeast value = new PlayerBeast(reader);
			playerBeast.Add(key, value);
		}
	}

	internal void AddKill(MonsterDef monsterDef)
	{
		AddKill(monsterDef.name);
		string name = monsterDef.name;
		if (!(name == "ruinghost"))
		{
			if (name == "ruinknight")
			{
				AddKill("ruinghost");
			}
		}
		else
		{
			AddKill("ruinknight");
		}
	}

	private void AddKill(string name)
	{
		if (!playerBeast.ContainsKey(name))
		{
			playerBeast.Add(name, new PlayerBeast());
		}
		playerBeast[name].kills++;
	}

	internal void AddDrop(MonsterDef monsterDef, int drop)
	{
		if (!playerBeast.ContainsKey(monsterDef.name))
		{
			playerBeast.Add(monsterDef.name, new PlayerBeast());
		}
		playerBeast[monsterDef.name].drops[drop]++;
	}

	internal bool HasBeast(MonsterDef mDef)
	{
		return playerBeast.ContainsKey(mDef.name);
	}

	internal void CopyFrom(PlayerBeasts copyBeasts)
	{
		playerBeast = new Dictionary<string, PlayerBeast>();
		foreach (KeyValuePair<string, PlayerBeast> item in copyBeasts.playerBeast)
		{
			playerBeast.Add(item.Key, new PlayerBeast(item.Value));
		}
	}

	internal bool HasBeastDrop(MonsterDef mDef, int i)
	{
		if (playerBeast.ContainsKey(mDef.name) && playerBeast[mDef.name].drops[i] > 0)
		{
			return true;
		}
		return false;
	}

	internal void AddKilledBy(Character character)
	{
		MonsterDef monsterDef = MonsterCatalog.catalog[character.monsterIdx];
		if (!playerBeast.ContainsKey(monsterDef.name))
		{
			playerBeast.Add(monsterDef.name, new PlayerBeast());
		}
		playerBeast[monsterDef.name].killedBy++;
	}

	internal void AddKilledBy(string name)
	{
		if (!playerBeast.ContainsKey(name))
		{
			playerBeast.Add(name, new PlayerBeast());
		}
		playerBeast[name].killedBy++;
	}

	internal void Reset()
	{
		playerBeast = new Dictionary<string, PlayerBeast>();
	}
}
