			return -1;
		}
		for (int i = 0; i < 4; i++)
		{
			GamePadState state = GamePad.GetState((PlayerIndex)i);
			if (!state.IsConnected)
			{
				continue;
			}
			switch (ConfigMgr.buttonConfig)
			{
			case 0:
				if (state.Buttons.A == ButtonState.Pressed || state.Buttons.Start == ButtonState.Pressed)
				{
					return i;
				}
				break;
			case 1:
				if (state.Buttons.B == ButtonState.Pressed || state.Buttons.Start == ButtonState.Pressed)
				{
					return i;
				}
				break;
			}
		}
		if (allowkeyboard && GlobalInputMgr.GetKeyboardEnter())
		{
			return 0;
		}
		return -1;
	}

