	internal static Player GetPlayerFromGamepad(int gIdx)
	{
		if (GameStateManager.gameState == 1 && GameStateManager.coopPlayerIdx > -1 && player[GameStateManager.coopPlayerIdx].gamepadIdx == player[GameStateManager.mainPlayerIdx].gamepadIdx && player[GameStateManager.coopPlayerIdx].gamepadIdx == gIdx)
		{
			return player[GameStateManager.coopPlayerIdx];
		}
		for (int i = 0; i < player.Length; i++)
		{
			if (player[i].active && player[i].gamepadIdx == gIdx)
			{
				return player[i];
			}
		}
		for (int j = 0; j < player.Length; j++)
		{
			if (!player[j].active)
			{
				player[j].gamepadIdx = gIdx;
				return player[j];
			}
		}
		return null;
	}

	internal static bool IsSaltCharacter(Character character)
	{
		if (character.origVec.X <= 0f || character.origVec.Y <= 0f)
		{
			return false;
		}
		return IsSaltCharacter(character.origVec);
	}

	internal static bool IsSaltCharacter(Vector2 origVec)
	{
		for (int i = 0; i < player.Length; i++)
		{
			if (player[i].active && player[i].saltOwnerVec.X > 0f && player[i].saltOwnerVec.Y > 0f && origVec.X == player[i].saltOwnerVec.X && origVec.Y == player[i].saltOwnerVec.Y)
			{
				player[i].lastSaltLoc = origVec;
				player[i].lastSaltLocReserve.X = (player[i].lastSaltLocReserve.Y = 0f);
				return true;
			}
		}
		return false;
	}

	internal static void RecoverSalt(Character c)
	{
		for (int i = 0; i < player.Length; i++)
		{
			if (player[i].active && player[i].saltOwnerVec.X > 0f && player[i].saltOwnerVec.Y > 0f && c.origVec.X == player[i].saltOwnerVec.X && c.origVec.Y == player[i].saltOwnerVec.Y)
			{
				player[i].AddSalt(player[i].saltTiedUp, 1f);
				player[i].saltTiedUp = 0;
				player[i].saltOwnerVec = default;
			}
		}
	}

