	internal static bool GetMainPlayerFlag(string flag)
	{
		Player mainPlayer = GetMainPlayer();
		if (mainPlayer != null && !string.IsNullOrEmpty(flag))
		{
			return mainPlayer.flags.Contains(flag);
		}
		return false;
	}

	internal static void CloseCoopPlayers(Player closingPlayer)
	{
		if (GameStateManager.pvpMode || GameStateManager.coopPlayerIdx <= -1)
		{
			return;
		}
		Character playerCharacter = CharMgr.GetPlayerCharacter(closingPlayer);
		Character playerCharacter2 = CharMgr.GetPlayerCharacter((closingPlayer.ID == GameStateManager.mainPlayerIdx) ? GetCoopPlayer() : GetMainPlayer());
		int layer = CharCols.GetLayer(playerCharacter.loc + new Vector2(0f, -10f));
		int layer2 = CharCols.GetLayer(playerCharacter2.loc + new Vector2(0f, -10f));
		bool flag = false;
		if (layer == 2 && layer2 == 2)
		{
			flag = true;
		}
		if (flag || (layer == layer2 && (playerCharacter.loc - playerCharacter2.loc).Length() < 500f) || !(playerCharacter.dyingFrame <= 0f) || !(playerCharacter2.hp > 0f) || !(playerCharacter2.dyingFrame <= 0f))
		{
			return;
		}
		bool flag2 = false;
		if (playerCharacter.platform > -1)
		{
			int type = MapMgr.entityMgr.platform[playerCharacter.platform].type;
			if ((uint)(type - 4) <= 1u)
			{
				MoveCoopCharToMainChar(playerCharacter2, playerCharacter);
				flag2 = true;
			}
		}
		if (!flag2)
		{
			MoveCoopCharToMainChar(playerCharacter, playerCharacter2);
		}
	}

	internal static void MoveCoopCharToMainChar(Character coopChar, Character mainChar)
	{
		coopChar.loc = mainChar.loc;
		coopChar.platform = mainChar.platform;
		coopChar.update.lastGroundedLoc = mainChar.update.lastGroundedLoc;
		coopChar.state = mainChar.state;
		if (mainChar.state == 0)
		{
			coopChar.anim.SetAnimation("idle");
		}
		else
		{
			coopChar.anim.SetAnimation("fly");
		}
		switch (mainChar.anim.animName)
		{
		case "ladder":
		case "ladderup":
		case "ladderdown":
		case "ladderslide":
			coopChar.anim.SetAnimation("ladder");
			coopChar.face = mainChar.face;
			coopChar.traj = default;
			break;
		}
		if (mainChar.buffs.GetUpsideDown())
		{
			coopChar.buffs.SetBuff(16, 30f);
		}
		else if (coopChar.buffs.GetUpsideDown())
		{
			coopChar.buffs.SetBuff(16, 0f);
		}
	}

	internal static void AddBeastKill(MonsterDef monsterDef, Character c)
	{
		if (GameStateManager.mainPlayerIdx > -1)
		{
			player[GameStateManager.mainPlayerIdx].playerBeasts.AddKill(monsterDef);
			player[GameStateManager.mainPlayerIdx].AddSalt(monsterDef, c);
			player[GameStateManager.mainPlayerIdx].kills++;
		}
		if (GameStateManager.coopPlayerIdx > -1)
		{
			player[GameStateManager.coopPlayerIdx].playerBeasts.AddKill(monsterDef);
			player[GameStateManager.coopPlayerIdx].AddSalt(monsterDef, c);
			player[GameStateManager.coopPlayerIdx].kills++;
		}
	}
