			break;
		default:
			return false;
		}
		return true;
	}

	private Vector2 UpdateMeleeReach(Character c, Vector2 location)
	{
		if (c.playerIdx < 0)
		{
			return location;
		}
		if (c.stats.GetCharmFlag(3))
		{
			float num = 10f;
			location.X += ((c.face == 1) ? 1f : (-1f)) * num;
		}
		int loadoutIdx = c.equipment.loadoutIdx;
		int category = c.equipment.loadout[loadoutIdx, 0].category;
		int catalogIdx = c.equipment.loadout[loadoutIdx, 0].catalogIdx;
		if (loadoutIdx > -1 && category > -1 && category == 0 && catalogIdx > -1 && catalogIdx < LootCatalog.category[0].loot.Length && LootCatalog.category[0].loot[catalogIdx].flags == 15)
		{
			float num2 = 10f;
			location.X += ((c.face == 1) ? 1f : (-1f)) * num2;
		}
		return location;
	}
}

