public class CharTrigRangedAtks : CharTrigActivator
{
	public override bool TryTrigs(int trig, Vector2 location, float rotation, int face, Vector2 straj, Character c, Part part, bool continuous, MonsterDef mDef, Vector2 scaling, bool flip, int lastFlame)
	{
		switch (trig)
		{
		{
			if (trig == 163)
			{
				Sound.Play3DSound("blunder", location, 0);
			}
			else
			{
				Sound.Play3DSound("bowfire", location, 0);
			}
			straj.Normalize();
			Vector2 gTraj = straj * new Vector2(1f, -1f);
			int flags = 10;
			if (c.playerIdx == -1)
			{
				switch (trig)
				{
					flags = 14;
					break;
					flags = 12;
					break;
					flags = 6;
					break;
				}
				if (c.charAI.targetIdx > -1 && MonsterCatalog.catalog[c.monsterIdx].type != 5 && MonsterCatalog.catalog[c.monsterIdx].type != 6)
				{
					Vector2 vector = CharMgr.character[c.charAI.targetIdx].loc - c.loc;
					if (CharMgr.character[c.charAI.targetIdx].buffs.GetUpsideDown())
					{
						vector.Y += 60f;
					}
					vector.Normalize();
					if (float.IsNaN(vector.X))
					{
						vector.X = 0f;
					}
					if (float.IsNaN(vector.Y))
					{
						vector.Y = 0f;
					}
					vector.Y += Rand.GetRandomFloat(-0.05f, 0f);
					straj = vector;
				}
				straj = c.trigs.GetValidProjTraj(gTraj, straj);
			}
			else
			{
				Player player = c.GetPlayer();
				if (player != null)
				{
					int num = c.update.lastAttackIdx + 1;
					if (c.GetMainhandWeapon(out var lootDef) && lootDef.type == 18 && !c.GetOffhandWeapon(out var _))
					{
						num = 1;
					}
					if (c.equipment.loadout[c.equipment.loadoutIdx, num].catalogIdx > -1 && c.equipment.loadout[c.equipment.loadoutIdx, num].invIdx > -1 && c.equipment.loadout[c.equipment.loadoutIdx, num].category == 4)
					{
						InvLoot invLoot = player.playerInv.inventory[c.equipment.loadout[c.equipment.loadoutIdx, num].invIdx];
						if (invLoot != null && invLoot.catalogIdx < LootCatalog.category[4].loot.Length)
						{
							switch (LootCatalog.category[4].loot[invLoot.catalogIdx].flags)
							{
								flags = 12;
								break;
								flags = 14;
								break;
								flags = 13;
								break;
								flags = 15;
								break;
								flags = 17;
								break;
								flags = 17;
								break;
								flags = 11;
								break;
							}
							if (!DebugMgr.unlimitedAmmo)
							{
								player.playerInv.inventory[c.equipment.loadout[c.equipment.loadoutIdx, num].invIdx].count--;
								if (player.playerInv.inventory[c.equipment.loadout[c.equipment.loadoutIdx, num].invIdx].count <= 0)
								{
									player.playerInv.inventory[c.equipment.loadout[c.equipment.loadoutIdx, num].invIdx] = null;
									c.equipment.loadout[c.equipment.loadoutIdx, num].invIdx = -1;
									c.equipment.loadout[c.equipment.loadoutIdx, num].catalogIdx = -1;
								}
							}
						}
					}
				}
				if ((trig == 148 || trig == 149 || trig == 150) && c.playerIdx > -1 && ConfigMgr.mouseControl == 1)
				{
					c.keys.keyMove = MouseMgr.mLoc - c.draw.drawCenter;
					c.keys.keyMove.Normalize();
					if (MouseMgr.mLoc.X > c.draw.drawCenter.X)
					{
						c.keys.keyRightRun = true;
						c.keys.keyLeftRun = false;
					}
					else
					{
						c.keys.keyLeftRun = true;
						c.keys.keyRightRun = false;
					}
				}
				straj = c.trigs.GetSteeredSTraj(c) * new Vector2(1f, -1f);
			}
			int num2 = -1;
			switch (trig)
			{
				num2 = ParticleManager.AddNormalParticle(117, location, straj * 1200f, 0f, part.rotation, flags, c.ID);
				break;
			{
				for (int i = 0; i < 15; i++)
				{
					_ = straj * 1500f + Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 500f;
					float angle = Trig.GetAngle(straj, default);
					float num3 = Rand.GetRandomFloat(-1f, 1f) * 0.8f;
					angle += num3 * 0.6f;
					float num4 = 1f - ((num3 < 0f) ? (0f - num3) : num3);
					int num5 = ParticleManager.AddAdditiveParticle(110, location, new Vector2((float)Math.Cos(angle), (float)Math.Sin(angle)) * Rand.GetRandomFloat(num4 / 4f, num4) * 3500f, Rand.GetRandomFloat(0.35f, 0.8f), angle, flags, c.ID);
					if (num5 > -1)
					{
						ParticleManager.particleList[5].particle[num5].grounded = true;
					}
				}
				num2 = ParticleManager.AddNormalParticle(126, location, straj * 1200f, 0f, part.rotation, flags, c.ID);
				break;
			}
				num2 = ParticleManager.AddAdditiveParticle(11, location, straj * 1600f, 0f, part.rotation, flags, c.ID);
				break;
			default:
				num2 = ParticleManager.AddNormalParticle(11, location, straj * 1200f, 0f, part.rotation, flags, c.ID);
				break;
			}
			if (num2 > -1)
			{
				c.trigs.torsoAngle = c.trigs.torsoGoalAngle;
			}
			return true;
		}
		default:
			return false;
		}
	}
}

